import{_ as a,o as t,c as n,ag as o}from"./chunks/framework.D9ghT4bC.js";const m=JSON.parse('{"title":"Installing on MacOS","description":"","frontmatter":{},"headers":[],"relativePath":"Other/Installing-on-macOS.md","filePath":"Other/Installing-on-macOS.md"}'),l={name:"Other/Installing-on-macOS.md"};function i(r,e,s,c,d,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="installing-on-macos" tabindex="-1">Installing on MacOS <a class="header-anchor" href="#installing-on-macos" aria-label="Permalink to &quot;Installing on MacOS&quot;">​</a></h1><p>There are currently several ways to install Unciv on MacOS.</p><p>It is recommended that you do not install from source, since the end result will be the same.</p><h1 id="installing-using-macports" tabindex="-1">Installing using MacPorts <a class="header-anchor" href="#installing-using-macports" aria-label="Permalink to &quot;Installing using MacPorts&quot;">​</a></h1><p>Details <a href="https://ports.macports.org/port/unciv/" target="_blank" rel="noreferrer">here</a> - simply run <code>sudo port install unciv</code> from command line and you&#39;re good to go!</p><p>Does not require a JDK to be preinstalled.</p><h2 id="installing-using-jar" tabindex="-1">Installing using JAR <a class="header-anchor" href="#installing-using-jar" aria-label="Permalink to &quot;Installing using JAR&quot;">​</a></h2><ol><li>If you don&#39;t already have Java 8 or OpenJDK (versions 11 and 18 do work) installed on your Mac, either</li></ol><ul><li>Download it from the <a href="https://java.com/en/download/" target="_blank" rel="noreferrer">official website</a>. Once you have downloaded the file, open it and follow the instructions on screen.</li><li>If you use <a href="https://brew.sh/" target="_blank" rel="noreferrer">Homebrew</a>, just run <code>brew install java</code></li></ul><ol start="2"><li>Now that you have Java installed, it&#39;s time to download the latest Unciv JAR. This can be done from the <a href="https://github.com/yairm210/Unciv/releases" target="_blank" rel="noreferrer">releases</a> screen here on Github. Download the file called <em>Unciv.jar</em>.</li><li>To run the game, you&#39;ll need to run <code>java -jar Unciv.jar</code> from a Terminal.</li><li>Alternatively, you could create an &#39;Unciv.sh&#39; file containing that line, and then run the new file to allow you to create shortcuts, etc.</li></ol><p><em>(Sadly Unciv does not auto update when installing it using this method on MacOS so you will need to download the latest Unciv.jar from Github every time you want to update the game.)</em></p><h2 id="installing-from-source" tabindex="-1">Installing from source <a class="header-anchor" href="#installing-from-source" aria-label="Permalink to &quot;Installing from source&quot;">​</a></h2><p>For instructions on how to install Unciv from source see <a href="./../Developers/Building-Locally.html">Building locally without Android Studio</a>. It is not recommended to use this method as it achieves the same result as the first method whilst being much more complicated and prone to errors along the way.</p><p><em>(Sadly Unciv does not auto update when installing it using this method on MacOS so you will need to follow these steps every time you want to update the game.)</em></p>',14)])])}const g=a(l,[["render",i]]);export{m as __pageData,g as default};
